(() => {
  const platform = document.body.dataset.platform || 'android';
  const embedded = new URLSearchParams(location.search).get('embed') === '1';
  if (embedded) document.body.classList.add('embed');

  const config = {
    android: { label:'Android', identity:'Continue with Google', provider:'G', purchase:'Google Play', chrome:'Material + Play Billing' },
    ios: { label:'iOS', identity:'Sign in with Apple', provider:'A', purchase:'App Store', chrome:'iOS + StoreKit' },
    mweb: { label:'Mobile Web / PWA', identity:'Continue with Google', provider:'G', purchase:'Razorpay / Stripe', chrome:'Installable browser app' },
    dweb: { label:'Desktop Web', identity:'Continue with Google', provider:'G', purchase:'Razorpay / Stripe', chrome:'Desktop browser' }
  }[platform];

  const routeLabels = {
    welcome:'Welcome', auth:'Sign in', explain:'How Longview works', availability:'Availability',
    'today-empty':'Empty Today', 'plan-create':'Describe Plan', 'plan-confirm':'Confirm Plan', reveal:'First day ready',
    today:'Today', 'completion-confirm':'Confirm completion', 'completion-done':'Step completed', portfolio:'Long-term Plans', 'clara-read':'Read-only recommendation', 'clara-home':'Ask Clara', 'clara-actions':'Quick Actions', 'clara-action-detail':'Action details', 'clara-chat':'Clara chat', 'clara-preview':'Clara change preview',
    kanban:'Kanban', calendar:'Calendar', 'schedule-loading':'Preparing day', 'schedule-proposal':'Schedule proposal', 'schedule-approved':'Approved day', 'break-confirm':'Take a break', 'break-done':'Break scheduled',
    settings:'Settings', appearance:'Appearance', goal:'Plan details', 'goal-task':"Today's task", 'goal-achievement':'Plan achieved', history:'Task history', decisions:'Decisions',
    research:'Research & Goal Brief', 'research-loading':'Finding research', 'research-cards':'Review research', 'brief-preview':'Brief update', 'brief-history':'Brief history',
    'goal-clara-home':'Plan Ask Clara', 'goal-clara-actions':'Plan Quick Actions', 'goal-clara-detail':'Plan action details', 'goal-clara-chat':'Plan Clara chat',
    plans:'Subscription plans', checkout:'Confirm subscription', stripe:'Stripe checkout', razorpay:'Razorpay checkout', 'payment-success':'Payment success', manage:'Manage subscription'
  };
  const routes = Object.keys(routeLabels);
  const routeSections = [
    ['Onboarding', ['welcome','auth','explain','availability','today-empty','plan-create','plan-confirm','reveal']],
    ['Dashboard', ['today','completion-confirm','completion-done','portfolio','kanban','calendar','schedule-loading','schedule-proposal','schedule-approved','break-confirm','break-done']],
    ['Ask Clara', ['clara-read','clara-home','clara-actions','clara-action-detail','clara-chat','clara-preview']],
    ['Goal', ['goal','goal-task','goal-achievement','history','decisions','research','research-loading','research-cards','brief-preview','brief-history']],
    ['Goal Clara', ['goal-clara-home','goal-clara-actions','goal-clara-detail','goal-clara-chat']],
    ['Account', ['settings','appearance','plans','checkout','stripe','razorpay','payment-success','manage']]
  ];
  const edgeCases = {
    normal:'Normal journey', 'auth-error':'Authentication failed', 'auth-popup':'Sign-in popup blocked', 'auth-conflict':'Account-link conflict', 'workspace-error':'Workspace setup failed', 'availability-empty':'No working day selected', 'availability-save-error':'Availability save failed', 'plan-save-error':'Plan save failed', 'plans-loading':'Plans loading', 'plans-empty':'No Plans yet', 'plans-load-error':'Plans failed to load', 'plan-details-missing':'Plan not found', 'plan-details-error':'Plan details unavailable', 'today-prepare-error':'Today failed to prepare', 'completion-save-error':'Completion failed to save', 'completion-duplicate':'Completion already recorded', offline:'Offline + pending sync', 'no-task':'No task scheduled today', 'draft-error':'Clara task draft failed',
    'schedule-error':'Schedule generation failed', 'run-cancelled':'Background run cancelled', 'run-timeout':'Background run timed out', 'partial-recovery':'Partial write recovery', 'research-error':'Research unavailable', 'brief-conflict':'Goal Brief version conflict', 'reflection-save-error':'Reflection save failed', 'payment-error':'Payment failed', grace:'Subscription grace period', 'clara-error':'Clara unavailable', 'clara-timeout':'Clara timed out', 'clara-malformed':'Clara response invalid', 'clara-clarification':'Clara needs clarification', 'clara-injection':'Unsafe instruction rejected', 'approval-stale':'Approval is stale', 'approval-duplicate':'Change already applied'
  };
  const appState = {
    route: location.hash.slice(1) && routes.includes(location.hash.slice(1)) ? location.hash.slice(1) : 'welcome',
    stack: [], edge:'normal', signedIn:false, anonymous:false, planCreated:false, taskDone:false,
    scheduleApproved:false, breakTaken:false, researchAccepted:0, briefVersion:3, subscription:'free',
    palette:'ocean', mode:'dark', font:'lora', size:'default', toast:'', demoMenu:'',
    planTitle:'Build SaaS Startup', planWhy:'Create a sustainable product business around a validated customer problem.'
  };
  const glyph = { today:'✓', kanban:'▥', calendar:'□', settings:'•••' };
  const root = document.getElementById('prototype');

  function routeGroup(route=appState.route) {
    if (['welcome','auth','explain','availability','today-empty','plan-create','plan-confirm','reveal'].includes(route)) return 'onboarding';
    if (['plans','checkout','stripe','razorpay','payment-success','manage'].includes(route)) return 'subscription';
    if (route.startsWith('goal') || ['history','decisions','research','research-loading','research-cards','brief-preview','brief-history'].includes(route)) return 'goal';
    if (route.startsWith('clara')) return 'clara';
    return 'dashboard';
  }
  function activeNav(route=appState.route) {
    if (route==='kanban') return 'kanban';
    if (route.startsWith('calendar') || route.startsWith('schedule') || route.startsWith('break')) return 'calendar';
    if (route==='settings' || route==='appearance' || routeGroup(route)==='subscription') return 'settings';
    return 'today';
  }
  function isNavless() { return routeGroup()==='onboarding' || routeGroup()==='subscription'; }
  function showBottomNav() { return !isNavless() && routeGroup()!=='clara' && !appState.route.includes('clara'); }
  function showClaraFab() { return appState.route==='today' || appState.route==='goal' || appState.route==='goal-task'; }
  function escapeHtml(value='') { return value.replace(/[&<>'"]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }
  function btn(label, go, cls='') { return `<button class="btn ${cls}" data-go="${go}">${label}</button>`; }
  function top(title, sub='', right='', back=true) {
    return `<div class="topline">${back?'<button class="link" data-back>‹ Back</button>':'<span></span>'}${right?`<button class="link" ${right.go?`data-go="${right.go}"`:''}>${right.label||right}</button>`:'<span></span>'}</div><h1 class="page-title">${title}</h1>${sub?`<p class="page-sub">${sub}</p>`:''}`;
  }
  function statusBar() { return platform==='ios'?`<span>9:41</span><span>5G&nbsp; 100%</span>`:`<span>10:24</span><span>Wi-Fi&nbsp; 92%</span>`; }
  function browserBar(path='app') { return `<div class="browser-chrome"><i class="browser-dot"></i><i class="browser-dot"></i><i class="browser-dot"></i><span class="address">longview.app/${path}</span></div>`; }
  function sideNav() {
    const on=activeNav(); return `<aside class="side"><div class="side-brand">Longview</div>${['today','kanban','calendar','settings'].map(x=>`<button class="side-item ${on===x?'on':''}" data-go="${x}"><i class="nav-glyph">${glyph[x]}</i>${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</aside>`;
  }
  function bottomNav() {
    const on=activeNav(); return `<nav class="bottom-nav">${['today','kanban','calendar','settings'].map(x=>`<button class="bottom-item ${on===x?'on':''}" data-go="${x}"><i class="nav-glyph">${glyph[x]}</i>${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</nav>`;
  }
  function demoBar() {
    const routeMenu=routeSections.map(([section,items])=>`<div class="demo-menu-section"><span>${section}</span>${items.map(route=>`<button class="demo-menu-item ${route===appState.route?'selected':''}" data-demo-route="${route}">${routeLabels[route]}</button>`).join('')}</div>`).join('');
    const edgeMenu=Object.entries(edgeCases).map(([edge,label])=>`<button class="demo-menu-item ${edge===appState.edge?'selected':''}" data-demo-edge="${edge}">${label}</button>`).join('');
    return `<header class="demo-bar"><div class="demo-identity"><span class="demo-brand">Longview</span><span class="demo-tag">${config.label} interactive prototype</span></div><div class="demo-menus"><div class="demo-menu ${appState.demoMenu==='route'?'open':''}"><button class="demo-menu-trigger" data-action="toggle-route-menu" aria-expanded="${appState.demoMenu==='route'}"><span><small>Screen</small>${routeLabels[appState.route]}</span><i>⌄</i></button><div class="demo-menu-panel route-menu" role="menu" aria-label="Prototype screen">${routeMenu}</div></div><div class="demo-menu ${appState.demoMenu==='edge'?'open':''}"><button class="demo-menu-trigger" data-action="toggle-edge-menu" aria-expanded="${appState.demoMenu==='edge'}"><span><small>Edge case</small>${edgeCases[appState.edge]}</span><i>⌄</i></button><div class="demo-menu-panel edge-menu" role="menu" aria-label="Edge case">${edgeMenu}</div></div></div><button class="demo-reset" data-action="reset">Reset journey</button></header>`;
  }
  function edgeBanner() {
    if (appState.edge==='normal') return '';
    return `<div class="edge-banner"><span>Demo state: ${edgeCases[appState.edge]}</span><button class="link" data-action="clear-edge">Return to normal</button></div>`;
  }
  function scaffold(content) {
    const path=routeGroup();
    let device='';
    if (platform==='dweb') device=`<section class="device desktop">${browserBar(path)}<div class="desktop-shell ${isNavless()?'navless':''}">${isNavless()?'':sideNav()}<main class="desktop-main">${edgeBanner()}${content}</main></div>${appState.toast?`<div class="toast">${appState.toast}</div>`:''}</section>`;
    else device=`<section class="device phone ${platform}">${platform==='ios'?'<i class="island"></i>':''}${platform==='mweb'?browserBar(path):`<div class="status">${statusBar()}</div>`}<main class="viewport">${edgeBanner()}${content}</main>${showBottomNav()?bottomNav():''}${showClaraFab()?`<button class="clara-fab" data-go="${appState.route.startsWith('goal')?'goal-clara-home':'clara-home'}">Clara</button>`:''}${appState.toast?`<div class="toast">${appState.toast}</div>`:''}</section>`;
    return `<div class="prototype-page">${embedded?'':demoBar()}<div class="prototype-stage">${device}</div></div>`;
  }

  function welcome() { return `<section class="screen"><div class="topline"><strong style="font:700 23px/1 var(--display)">Longview</strong><button class="link" data-go="auth">Sign in</button></div><div class="hero"><span class="clara-mark">C</span><h1>Make progress without rebuilding the plan every day.</h1><p>Longview turns a meaningful Plan into one manageable day at a time. Clara keeps the context when life changes.</p></div>${btn('Get started','auth','primary')}${btn('Explore the demo','today','ghost')}${platform==='mweb'?`<div class="notice"><div><strong>Install Longview</strong><span>Use it from your home screen and keep the app shell available offline.</span></div><button class="link" data-action="install">Install</button></div>`:''}</section>`; }
  function auth() {
    const authNotice={
      'auth-error':['Couldn’t sign in','The provider did not complete sign-in','No account was created. Try again or continue anonymously.'],
      'auth-popup':['Popup blocked','Your browser stopped the Google window','Allow popups for Longview, retry, or continue anonymously.'],
      'auth-conflict':['Account already connected','This Google account belongs to another workspace','Nothing was merged. Your anonymous workspace remains unchanged.'],
      'workspace-error':['Workspace unavailable','Your account is still protected','No duplicate was created. Check the connection and retry workspace setup.']
    }[appState.edge]; return `<section class="screen">${top('Choose how to begin','Anonymous use is fully supported. Link it later without losing your Plans.','',true)}${authNotice?`<div class="notice" style="border-color:var(--rose)"><span class="badge rose">${authNotice[0]}</span><div><strong>${authNotice[1]}</strong><span>${authNotice[2]}</span></div></div>`:''}${appState.edge==='auth-conflict'?btn('Use existing Google workspace','settings','primary'):''}<button class="btn primary" data-action="provider"><b>${config.provider}</b>&nbsp; ${config.identity}</button>${platform==='ios'?'<button class="btn" data-action="google"><b>G</b>&nbsp; Continue with Google</button>':''}<div class="field" style="text-align:center;color:var(--faint);font-size:9px">or</div><button class="btn" data-action="anonymous">Continue anonymously</button><p class="meta" style="margin-top:12px">An anonymous account works immediately. Link it from Settings to protect access across devices.</p></section>`;
  }
  function explain() { return `<section class="screen">${top('A calmer way to follow through','Longview plans only what you can act on next.','',true)}<div class="feature"><i>1</i><div><b>Name the Plan</b><span>Describe the outcome and why it matters.</span></div></div><div class="feature"><i>2</i><div><b>Approve one day</b><span>Longview proposes only today’s schedule based on your capacity.</span></div></div><div class="feature"><i>3</i><div><b>Keep the context</b><span>Tasks, decisions, research, and reflections remain connected.</span></div></div>${btn('Set my available time','availability','primary')}${btn('Use defaults','today-empty','ghost')}</section>`; }
  function availability() {
    const issue=appState.edge==='availability-empty'?`<div class="notice" style="border-color:var(--rose)"><span class="badge rose">Choose a day</span><div><strong>Longview needs at least one working day</strong><span>No schedule was created. Select a day or decide later with the documented defaults.</span></div></div>`:appState.edge==='availability-save-error'?`<div class="notice" style="border-color:var(--rose)"><span class="badge rose">Not saved</span><div><strong>Your previous availability is unchanged</strong><span>The selected days are still here. Check the connection and try again.</span></div></div>`:'';
    return `<section class="screen">${top('When can Longview plan for you?','This is only a starting point. You can change it later.','',true)}${issue}<div class="field"><label>Usual working days</label><div class="days">${['M','T','W','T','F','S','S'].map((x,i)=>`<button class="day ${[0,2,4,5].includes(i)?'on':''}" data-action="toggle-day">${x}</button>`).join('')}</div></div><div class="field"><label>Time available per day</label><div class="input">2 hours</div></div><div class="field"><label>Preferred time</label><div class="input">Morning · 7:00–9:00</div></div>${btn(appState.edge==='availability-save-error'?'Try saving again':'Finish setup','today-empty','primary')}${btn('Decide later','today-empty','ghost')}</section>`;
  }
  function todayEmpty() { return `<section class="screen">${top('Today','Sun, Aug 2','',false)}<div class="empty"><div class="empty-icon">I</div><h2>Your first Plan starts here</h2><p>Create a Plan and Longview will prepare the first manageable task for an available day.</p>${btn('Create a Plan','plan-create','primary')}${btn('Ask Clara what to plan','clara-home','ghost')}</div></section>`; }
  function planCopy() {
    if(/longview|launch|product|app|saas|startup/i.test(appState.planTitle)) return {
      summary:'Turn the current product into a focused, release-ready experience without losing the calm planning model.',
      target:'October 2026', first:'Define launch readiness',
      task:'List the five conditions that must be true before release, then mark the one that needs attention this week.',
      days:'Mon, Tue, Thu, Fri'
    };
    return {
      summary:'Turn the long-term outcome into a bounded next step while preserving its constraints and rationale.',
      target:'December 2026', first:'Define the first measurable milestone',
      task:'Write the observable result that would prove meaningful progress, then identify the smallest test for this week.',
      days:'Mon, Wed, Fri, Sat'
    };
  }
  function planCreate() { return `<section class="screen">${top('What do you want to make progress on?','Use one sentence. Clara will shape the details around it.','',true)}<div class="field"><label>Plan</label><textarea class="input" id="planTitle">${escapeHtml(appState.planTitle)}</textarea></div><div class="field"><label>Why it matters</label><textarea class="input" id="planWhy">${escapeHtml(appState.planWhy)}</textarea></div>${btn('Shape this Plan','plan-confirm','primary')}<button class="btn" data-action="speak">Speak instead</button></section>`; }
  function planConfirm() { const copy=planCopy(); return `<section class="screen">${top('Confirm Plan details','Clara extracted what it could and suggested the rest.','',true)}<div class="card"><span class="section-label">Plan <span class="badge blue">From your words</span></span><h2 class="card-title">${escapeHtml(appState.planTitle)}</h2><p class="card-copy">${copy.summary}</p><div class="field"><label>Target <span class="badge blue">From your words</span></label><div class="input">${copy.target}</div></div><div class="field"><label>Working days <span class="badge violet">Clara suggests</span></label><div class="days">${['M','T','W','T','F','S','S'].map((x,i)=>`<button class="day ${[0,2,4,5].includes(i)?'on':''}">${x}</button>`).join('')}</div></div><div class="field"><label>Weekly allocation <span class="badge violet">Clara suggests</span></label><div class="input">6 hours · primary focus</div></div></div><button class="btn primary" data-action="create-plan">Create Plan</button>${btn('Adjust details','plan-create','ghost')}</section>`; }
  function reveal() {
    const copy=planCopy();
    if(appState.edge==='draft-error') return `<section class="screen">${top('Plan created','Your Plan is safe, but the first task could not be drafted.','',false)}<div class="card"><h2 class="card-title">${escapeHtml(appState.planTitle)}</h2><p class="meta">Created just now</p></div><div class="notice" style="border-color:var(--rose)"><span class="badge rose">Draft failed</span><div><strong>Clara could not prepare today’s task</strong><span>The Plan was not lost. Retry or write the first task yourself.</span></div></div><button class="btn primary" data-action="retry-draft">Retry draft</button>${btn('Write it myself','goal-task')}${btn('Go to Today','today','ghost')}</section>`;
    return `<section class="screen">${top('Your first step is ready','The Plan is saved. Nothing else was changed.','',false)}<div class="card"><div class="task-head"><div><h2 class="card-title">${escapeHtml(appState.planTitle)}</h2><p class="meta">Nearest active target</p></div><span class="badge green">Active</span></div></div><div class="card task-card"><span class="section-label">Today · 60 min</span><h2 class="card-title">${copy.first}</h2><p class="card-copy">${copy.task}</p><span class="badge blue">Prepared from your Plan</span></div>${btn('Go to Today','today','primary')}</section>`;
  }
  function today() {
    if(appState.edge==='today-prepare-error') return `<section class="screen">${top('Today','Sun, Aug 2','',false)}<div class="empty" style="margin-top:34px"><div class="empty-icon">!</div><h2>Today couldn’t be prepared</h2><p>Your Plans are unchanged. Check your connection and try again.</p><button class="btn primary" data-action="clear-edge">Try again</button>${btn('View Plans','portfolio','ghost')}</div></section>`;
    if(appState.edge==='offline') return `<section class="screen">${top('Today','Sun, Aug 2','',false)}<div class="notice" style="border-color:var(--amber)"><span class="badge amber">Offline</span><div><strong>Using your last synced day</strong><span>Completions will sync when the connection returns.</span></div></div>${taskCards()}<div class="toast" style="position:static;transform:none;width:100%;margin-top:12px">1 completion waiting to sync</div></section>`;
    if(appState.edge==='no-task') return `<section class="screen">${top('Today','Sun, Aug 2','',false)}<div class="card"><h2 class="card-title">${escapeHtml(appState.planTitle)}</h2><p class="meta">Next scheduled task · Monday, Aug 3</p></div><div class="empty" style="margin-top:34px"><div class="empty-icon">✓</div><h2>Nothing scheduled today</h2><p>The next startup validation block is Monday. You can rest, add a small task, or ask Clara to rebalance the portfolio.</p>${btn('Ask Clara','clara-home','primary')}${btn('Add a task','goal-task')}</div></section>`;
    return `<section class="screen">${top('Today','Sun, Aug 2',{label:'3 Plans',go:'portfolio'},false)}<div class="metrics"><div class="metric"><b>${appState.taskDone?'1':'2'}</b><span>tasks left</span></div><div class="metric"><b>${appState.taskDone?'30m':'90m'}</b><span>planned time</span></div><div class="metric"><b>${appState.taskDone?'1/2':'0/2'}</b><span>completed</span></div></div><button class="notice" data-go="clara-read"><span class="clara-mark">C</span><div><strong>Ask Clara about this step</strong><span>See one read-only recommendation and the Plan facts behind it</span></div><span class="chev">›</span></button>${taskCards()}</section>`;
  }
  function taskCards() { return `${appState.taskDone?'':`<div class="section-label">Build SaaS Startup</div><div class="card task-card"><div class="task-head"><div><h2 class="card-title">Validate onboarding with target users</h2><p class="meta">60 min · morning</p></div><span class="badge blue">Today</span></div><p class="card-copy">Run two focused sessions and record where users fail to reach the first useful outcome.</p><div class="task-actions">${btn('Complete','completion-confirm','primary')}${btn('Review','goal-task')}</div></div>`}<div class="section-label" style="margin-top:15px">Learn AI / ML Application</div><div class="card task-card" style="border-left-color:var(--rose)"><div class="task-head"><div><h2 class="card-title">Evaluate the retrieval baseline</h2><p class="meta">30 min · flexible</p></div><span class="badge amber">Conflict</span></div><p class="card-copy">Run the saved evaluation set and capture groundedness failures before changing the model.</p></div>`; }

  function completionConfirm() { return `<section class="screen">${top('Mark this step complete?','Your Plan and schedule will stay the same.','',true)}<div class="card task-card"><span class="section-label">Build SaaS Startup · Today</span><h2 class="card-title">Validate onboarding with target users</h2><p class="card-copy">This records one immutable completion for today. It does not create another task or change the Plan.</p><span class="badge blue">60 minutes</span></div>${appState.edge==='completion-save-error'?`<div class="notice" style="border-color:var(--rose)"><span class="badge rose">Not saved</span><div><strong>Your step is still open</strong><span>Check your connection and try again with the same completion.</span></div></div>`:''}<button class="btn primary" data-action="complete-task">${appState.edge==='completion-save-error'?'Try again':'Confirm completion'}</button>${btn('Keep working','today','ghost')}</section>`; }
  function completionDone() { return `<section class="screen">${top('Today’s step is complete','Your Plan remains active.','',false)}${appState.edge==='completion-duplicate'?`<div class="notice"><span class="badge blue">Already recorded</span><div><strong>The original completion was returned</strong><span>No second event was written and the completed time is unchanged.</span></div></div>`:''}<div class="empty" style="margin-top:34px"><div class="empty-icon">✓</div><h2>Meaningful progress recorded</h2><p>Validate onboarding with target users · 60 minutes. No new schedule was created.</p>${btn('Return to Today','today','primary')}${btn('View all Plans','portfolio')}</div></section>`; }

  function portfolio() {
    const plans = [
      ['Build SaaS Startup','Primary focus','6h this week','Launch validated beta · Oct 2026','Validate onboarding with five target users','50','green'],
      ['Learn AI / ML Application','Maintain momentum','4h this week','Ship one applied portfolio project · Nov 2026','Implement and evaluate the retrieval baseline','33','blue'],
      ['Build a House','Prepare, don’t accelerate','2h this week','Construction-ready plan · 2028','Compare land, financing, and contractor constraints','17','amber']
    ];
    if(appState.edge==='plans-loading') return `<section class="screen">${top('Long-term Plans','Your meaningful outcomes in one place.','',true)}<div class="loading"><div class="spinner"></div>Loading your Plans…</div></section>`;
    if(appState.edge==='plans-empty') return `<section class="screen">${top('Long-term Plans','Your meaningful outcomes in one place.','',true)}<div class="empty" style="margin-top:34px"><div class="empty-icon">I</div><h2>No Plans yet</h2><p>Create your first Plan and it will appear here.</p>${btn('Create a Plan','plan-create','primary')}</div></section>`;
    if(appState.edge==='plans-load-error') return `<section class="screen">${top('Long-term Plans','Your meaningful outcomes in one place.','',true)}<div class="empty" style="margin-top:34px"><div class="empty-icon">!</div><h2>Your Plans couldn’t be loaded</h2><p>Check your connection and try again. Nothing has been changed.</p><button class="btn primary" data-action="clear-edge">Try again</button>${btn('Return to Today','today','ghost')}</div></section>`;
    return `<section class="screen">${top('Long-term Plans','Three outcomes sharing one finite week.',{label:'Ask Clara',go:'clara-chat'},true)}<div class="portfolio-capacity"><div><b>12h</b><span>weekly capacity</span></div><div><b>6 / 4 / 2</b><span>hours allocated</span></div><div><b>1</b><span>active tradeoff</span></div></div><div class="notice portfolio-insight"><span class="clara-mark">C</span><div><strong>Protect startup validation this week</strong><span>Keep AI/ML moving with one build block. Hold house work to decision preparation until financing assumptions are clearer.</span></div></div><div class="portfolio-list">${plans.map(plan=>`<button class="portfolio-plan" data-go="goal"><div class="portfolio-head"><div><span class="badge ${plan[6]}">${plan[1]}</span><h2>${plan[0]}</h2></div><strong>${plan[2]}</strong></div><p>${plan[3]}</p><div class="portfolio-next"><span>Next</span>${plan[4]}</div><div class="portfolio-progress"><i style="width:${plan[5]}%"></i></div></button>`).join('')}</div><p class="meta portfolio-foot">Clara can recommend allocation changes, but each schedule change still requires approval.</p></section>`;
  }

  function claraRead() {
    if(['clara-timeout','clara-error','clara-malformed','clara-clarification','clara-injection'].includes(appState.edge)) {
      const copy=appState.edge==='clara-timeout'?['Clara took too long','The request stopped safely.']:appState.edge==='clara-malformed'?['Clara’s response could not be used','The response did not match the expected format.']:appState.edge==='clara-clarification'?['Clara needs one detail','Which result would count as proof that this Plan moved forward?']:appState.edge==='clara-injection'?['Unsafe instruction rejected','The response tried to expand context or authorize a change, so Longview discarded it.']:['Clara is unavailable','The request could not be completed.'];
      return `<section class="screen">${top('Ask Clara about this step','No Plan or schedule changes are allowed here.','',true)}<div class="empty" style="margin-top:38px"><div class="empty-icon">C</div><h2>${copy[0]}</h2><p>${copy[1]} Your Today step and Plan are unchanged.</p><button class="btn primary" data-action="clear-edge">Try again</button>${btn('Return to Today','today','ghost')}</div></section>`;
    }
    return `<section class="screen">${top('Clara’s recommendation','Read-only guidance for today’s selected step.','',true)}<div class="notice"><span class="badge blue">Context used</span><div><strong>Build SaaS Startup</strong><span>Target Oct 2026 · 6 hours/week · 60-minute Today step</span></div></div><div class="card" style="border-color:var(--accent)"><span class="section-label">Read-only recommendation · medium confidence</span><h2 class="card-title">Protect the smallest proof of progress</h2><p class="card-copy">Finish the selected customer-validation step before adding new work.</p><p class="meta">This creates evidence for the nearest active target while staying inside the current weekly allocation.</p></div><div class="notice"><span class="badge green">Safe boundary</span><div><strong>Nothing was changed</strong><span>Clara cannot edit the Plan, schedule, or completion from this recommendation.</span></div></div>${btn('Return to Today','today','primary')}</section>`;
  }
  function claraHome(goal=false) { const ctx=goal?'Build SaaS Startup':'Today'; return `<section class="screen">${top('Ask Clara',`Choose how Clara can help with ${goal?'this Plan':'Today'}.`,{label:'History',go:goal?'history':'clara-chat'},true)}<div class="clara-context"><span class="clara-mark">C</span><div><b>Context ${goal?'locked':'ready'} · ${ctx}</b><p>${goal?'Goal Brief v4, tasks, schedule, research, history, and decisions for this Plan only.':'3 active Plans, 2 tasks, 12 weekly hours, deadlines, and related decisions.'}</p></div></div><div class="doors"><button class="door" data-go="${goal?'goal-clara-actions':'clara-actions'}"><i class="door-icon">↗</i><div><b>Quick Actions</b><p>See what Clara can do on this screen, grouped by outcome.</p></div><span class="chev">›</span></button><button class="door" data-go="${goal?'goal-clara-chat':'clara-chat'}"><i class="door-icon">“ ”</i><div><b>Chat with Clara</b><p>Ask naturally. The context is already attached.</p></div><span class="chev">›</span></button></div><div class="notice"><span class="badge ${goal?'violet':'blue'}">${goal?'Restricted':'Boundary'}</span><div><strong>${goal?'This Plan only':'Portfolio-aware context'}</strong><span>${goal?'Unrelated Plans cannot be read or changed here.':'Clara can compare all three Plans and previews every change.'}</span></div></div></section>`; }
  function claraActions(goal=false) { const cats=goal?[['Today’s task','Explain, shorten, reschedule, or reflect on today’s validation work.','3'],['Plan and schedule','Adjust customer sessions, milestones, or weekly allocation.','4'],['Research and brief','Find evidence, review cards, or explain brief changes.','3'],['Decisions and progress','Review history, record reasoning, or identify a risk.','3']]:[['Plan my day','Build, adjust, or regenerate today’s schedule.','3'],['Prioritize','Compare all three Plans, protect deadlines, or choose what is next.','3'],['Move work','Carry forward, reschedule, shorten, or take a break.','4'],['Review progress','Summarize completed work, risks, and decisions.','3']]; return `<section class="screen">${top('Quick Actions',goal?'Build SaaS Startup':'Available for Today · 3 active Plans',{label:'Chat',go:goal?'goal-clara-chat':'clara-chat'},true)}<div class="category-grid">${cats.map((c,i)=>`<button class="category" data-go="${goal?'goal-clara-detail':'clara-action-detail'}"><span class="count">${c[2]}</span><b>${c[0]}</b><p>${c[1]}</p></button>`).join('')}</div><div class="notice"><span class="badge ${goal?'violet':'green'}">${goal?'Scope':'Safe by default'}</span><div><strong>${goal?'Bound to this Plan':'Review before applying'}</strong><span>${goal?'Every action stays inside Build SaaS Startup.':'Every allocation or schedule write appears in a concrete preview.'}</span></div></div></section>`; }
  function claraActionDetail(goal=false) { const actions=goal?[['R','Find fresh research','Search for evidence relevant to Goal Brief v4.'],['✓','Review saved cards','Open accepted, rejected, and deferred cards.'],['v','Explain the latest brief','Relate v4 to the evidence and Decisions that changed it.']]:[['✓','Build today’s schedule','Use all three Plans, capacity, deadlines, and preferred times.'],['↕','Reorder today','Explain the cross-goal tradeoff before changing start times.'],['↻','Try a different allocation','Generate an alternative without changing the approved day.']]; return `<section class="screen">${top(goal?'Research and brief':'Plan my day',`Quick Actions · ${goal?'Build SaaS Startup':'Today'}`,'',true)}<div class="card">${actions.map(a=>`<button class="action-row" data-go="${goal?'research':'clara-preview'}"><i class="action-icon">${a[0]}</i><div><b>${a[1]}</b><p>${a[2]}</p></div><span class="chev">›</span></button>`).join('')}</div><p class="meta">${goal?'Research can propose a new brief version, but cannot update it silently.':'Every move or duration change is reviewed before it is applied.'}</p></section>`; }
  function claraChat(goal=false) {
    if(appState.edge==='clara-error') return `<section class="screen">${top('Clara',goal?'Build SaaS Startup':'Today','',true)}<div class="empty" style="margin-top:38px"><div class="empty-icon">C</div><h2>Clara is unavailable</h2><p>Your Plans, allocations, and schedule are unchanged. The conversation draft remains on this device.</p><button class="btn primary" data-action="retry-clara">Try again</button>${btn('Return without changes',goal?'goal':'today','ghost')}</div></section>`;
    return `<section class="screen">${top('Clara',goal?'Using Build SaaS Startup · restricted':'Using Today · 3 Plans',{label:'Actions',go:goal?'goal-clara-actions':'clara-actions'},true)}<div class="prompts">${(goal?['Explain today’s validation','Is this Plan on track?','Review my latest decision']:['What should I protect?','Rebalance this week','Review my risks']).map(x=>`<button class="prompt" data-action="prompt">${x}</button>`).join('')}</div><div class="chat"><div class="bubble">${goal?'I’m using Goal Brief v4, the validation schedule, current Decisions, and recent customer evidence.':'Startup validation and the AI/ML evaluation both want the morning. House preparation has no external deadline this week. You have 90 minutes today.'}</div><div class="bubble you">${goal?'Should I add another feature before testing?':'Protect the startup. What can move?'}</div><div class="bubble">${goal?'Not yet. Validate the first useful outcome before expanding scope.':'Keep 60 minutes for startup validation. Move the 30-minute retrieval evaluation to Wednesday. Keep house work in its Saturday decision block.'}</div></div>${goal?`<div class="card"><span class="section-label">Suggested follow-up</span><h2 class="card-title">Review after five customer sessions</h2><p class="card-copy">No scope change yet.</p><button class="btn" data-action="reminder">Add review reminder</button></div>`:`<div class="card"><span class="section-label">Proposed change</span><h2 class="card-title">Move “Evaluate retrieval baseline”</h2><p class="meta">Today, 8:15 → Wed, Aug 5, 7:30</p><div class="row" style="margin-top:10px"><button class="btn primary" data-go="clara-preview">Review change</button>${btn('Keep today','today')}</div></div>`}<div class="composer"><input class="input" placeholder="${goal?'Ask about this Plan':'Ask across all 3 Plans'}"><button class="send" data-action="send">↑</button></div></section>`;
  }
  function claraPreview() {
    if(appState.edge==='approval-stale') return `<section class="screen">${top('Review Clara’s change','The underlying schedule changed after this preview.','',true)}<div class="empty" style="margin-top:36px"><div class="empty-icon">!</div><h2>This preview is out of date</h2><p>Nothing was applied. Refresh the current day before reviewing a new proposal.</p>${btn('Refresh proposal','clara-chat','primary')}${btn('Return unchanged','today','ghost')}</div></section>`;
    if(appState.edge==='approval-duplicate') return `<section class="screen">${top('Change already applied','The original audited result was returned.','',true)}<div class="notice"><span class="badge green">No duplicate write</span><div><strong>Retrieval evaluation is already on Wednesday</strong><span>The schedule version and audit identifier remain unchanged.</span></div></div>${btn('View updated Today','today','primary')}</section>`;
    return `<section class="screen">${top('Review Clara’s change','Nothing moves until you apply it.','',true)}<div class="card"><span class="section-label">Keep · Build SaaS Startup</span><h2 class="card-title">Validate onboarding with target users</h2><p class="meta">Today · 7:00 AM · 60 min</p></div><div class="card" style="border-color:var(--accent)"><span class="section-label">Move · Learn AI / ML Application</span><h2 class="card-title">Evaluate retrieval baseline</h2><p class="meta">Today, 8:15 → Wednesday, Aug 5, 7:30</p></div><div class="notice"><span class="badge green">Result</span><div><strong>Startup validation gets the protected morning block</strong><span>The house Plan remains unchanged in Saturday’s 2-hour allocation.</span></div></div><button class="btn primary" data-action="apply-clara">Apply change</button>${btn('Adjust first','calendar')}${btn('Cancel','today','ghost')}</section>`;
  }

  function kanban() { return `<section class="screen">${top('Kanban','Tasks grouped by status. Filter: All 3 Plans','',false)}<div class="board"><div class="lane"><div class="lane-title">To do · 3</div><button class="board-task" data-go="goal-task">Interview target users</button><button class="board-task">Compare financing assumptions</button></div><div class="lane"><div class="lane-title">In progress · 2</div><button class="board-task" data-go="goal-task">Validate onboarding</button><button class="board-task">Evaluate retrieval baseline</button></div><div class="lane"><div class="lane-title">Done · 8</div><button class="board-task">Define activation event</button><button class="board-task">Choose evaluation set</button></div></div><div class="notice"><span class="badge blue">Portfolio</span><div><strong>Build SaaS Startup · primary focus</strong><span>6 of 12 weekly hours allocated</span></div><button class="link" data-go="portfolio">Change</button></div></section>`; }
  function calendar() {
    if(appState.edge==='schedule-error') return `<section class="screen">${top('Calendar','Sunday, Aug 2','',false)}<div class="empty" style="margin-top:38px"><div class="empty-icon">!</div><h2>Couldn’t prepare the day</h2><p>Your existing schedule is unchanged. Retry generation or arrange today manually.</p><button class="btn primary" data-action="generate-schedule">Try again</button>${btn('Arrange manually','schedule-proposal')}${btn('Take a break','break-confirm','ghost')}</div></section>`;
    if(appState.edge==='run-timeout') return `<section class="screen">${top('Calendar','Background run stopped safely','',false)}<div class="empty" style="margin-top:38px"><div class="empty-icon">!</div><h2>The run took too long</h2><p>Your approved schedule is unchanged. Retry starts a new correlated run.</p><button class="btn primary" data-action="generate-schedule">Start a new run</button>${btn('Keep current day','today','ghost')}</div></section>`;
    if(appState.edge==='partial-recovery') return `<section class="screen">${top('Calendar','Recovering the last approved version','',false)}<div class="notice" style="border-color:var(--amber)"><span class="badge amber">Reconciling</span><div><strong>No mixed schedule is visible</strong><span>Longview is completing or rolling back the transaction before showing success.</span></div></div>${scheduleBlocks()}${btn('Return after recovery','schedule-approved','primary')}</section>`;
    return `<section class="screen">${top('Calendar','Schedule one day at a time.','',false)}<div class="notice"><span class="clara-mark">C</span><div><strong>${appState.scheduleApproved?'Today is approved':'Today needs your approval'}</strong><span>${appState.scheduleApproved?'90 of 120 minutes scheduled across 2 Plans.':'Longview can prepare 2 tasks within your capacity.'}</span></div></div>${appState.scheduleApproved?scheduleBlocks():`<div class="empty" style="margin-top:38px"><div class="empty-icon">□</div><h2>Prepare Sunday</h2><p>Longview will order only today’s tasks across the portfolio. You review every block before it is saved.</p><button class="btn primary" data-action="generate-schedule">Prepare today</button>${btn('Take a break today','break-confirm','ghost')}</div>`}</section>`; }
  function scheduleBlocks() { return `<div class="schedule"><div class="slot"><time>7:00</time><div class="slot-body"><b>Validate onboarding with target users</b><span>60 min · Build SaaS Startup</span></div></div><div class="slot"><time>8:15</time><div class="slot-body"><b>Evaluate retrieval baseline</b><span>30 min · Learn AI / ML Application</span></div></div></div>`; }
  function scheduleLoading() { if(appState.edge==='run-cancelled') return `<section class="screen">${top('Run cancelled','The last safe checkpoint was preserved.','',true)}<div class="empty" style="margin-top:38px"><div class="empty-icon">□</div><h2>No schedule was replaced</h2><p>Resume with a new run or return to the existing approved day.</p>${btn('Start again','calendar','primary')}${btn('Return unchanged','today','ghost')}</div></section>`; return `<section class="screen">${top('Preparing Sunday','Clara is fitting work across all three Plans.','',true)}<div class="loading"><div class="spinner"></div>Run LV-20260802-014 · checkpoint 2/4 · checking operating modes, deadlines, task types, and 120 available minutes…</div></section>`; }
  function scheduleProposal() { return `<section class="screen">${top('Sunday, Aug 2','Longview prepared one portfolio-aware day for review.',{label:'Try again',go:'schedule-loading'},true)}<div class="notice"><span class="clara-mark">C</span><div><strong>90 minutes fit into 120 available</strong><span>Startup validation is first because it is the primary focus and requires live participants.</span></div></div>${scheduleBlocks()}<div class="row" style="margin-top:13px"><button class="btn primary" data-action="approve-day">Approve day</button>${btn('Adjust','calendar')}</div>${btn('Take a break today','break-confirm','ghost')}</section>`; }
  function scheduleApproved() { return `<section class="screen">${top('Sunday, Aug 2','Approved · 90 of 120 minutes',{label:'Edit day',go:'schedule-proposal'},true)}${scheduleBlocks()}<div class="notice"><span class="badge green">Saved</span><div><strong>Your portfolio-aware day is ready</strong><span>Build a House remains in its Saturday allocation. Longview will not schedule another day until you ask.</span></div></div>${btn('Return to Today','today','primary')}</section>`; }
  function breakConfirm() { return `<section class="screen">${top('Take a break today?','Nothing will be marked complete.','',true)}<div class="card"><h2 class="card-title">2 tasks will move</h2><div class="setting"><div><b>Validate onboarding</b><span>Next customer window · Monday</span></div><span>60m</span></div><div class="setting"><div><b>Evaluate retrieval baseline</b><span>Next learning block · Wednesday</span></div><span>30m</span></div></div><div class="notice"><span class="badge amber">Check</span><div><strong>Weekly allocations remain 6 / 4 / 2 hours</strong><span>Longview will ask you to approve each affected day separately.</span></div></div><button class="btn primary" data-action="confirm-break">Take the break</button>${btn('Keep today’s plan','calendar','ghost')}</section>`; }
  function breakDone() { return `<section class="screen">${top('Take the day','Your work has been carried to its next eligible blocks.','',false)}<div class="empty" style="margin-top:34px"><div class="empty-icon">✓</div><h2>Sunday is clear</h2><p>Startup validation moved to Monday and AI/ML evaluation to Wednesday. Nothing was marked complete; both days remain unapproved.</p>${btn('Return to Today','today','primary')}${btn('Preview next blocks','calendar')}</div></section>`; }

  function settings() { return `<section class="screen">${top('Settings','Account, planning preferences, and privacy.','',false)}${platform==='mweb'?`<div class="notice"><div><strong>Install Longview</strong><span>Home-screen access and an offline app shell.</span></div><button class="link" data-action="install">Install</button></div>`:''}<div class="card"><span class="section-label">Account</span><div class="setting"><div><b>${appState.anonymous?'Anonymous account':config.identity.replace('Continue with ','')}</b><span>${appState.anonymous?'Link to protect your data':'alok@example.com'}</span></div><button class="link" data-go="auth">${appState.anonymous?'Link':'Manage'}</button></div><div class="setting"><div><b>Sync</b><span>${appState.edge==='offline'?'Changes pending':'Up to date'}</span></div><span class="badge ${appState.edge==='offline'?'amber':'green'}">${appState.edge==='offline'?'Offline':'Synced'}</span></div></div><div class="card"><span class="section-label">Planning</span><button class="setting" data-go="availability"><div><b>Availability</b><span>12 hours/week · 3 active Plans</span></div><span>›</span></button><div class="setting"><div><b>Daily reminder</b><span>7:00 AM</span></div><i class="toggle"></i></div><button class="setting" data-go="appearance"><div><b>Appearance</b><span>${appState.palette} · ${appState.mode} · ${appState.font}</span></div><span>›</span></button></div><div class="card"><button class="setting" data-go="${appState.subscription==='active'?'manage':'plans'}"><div><b>${appState.subscription==='active'?'Longview Pro':'Subscription'}</b><span>${appState.subscription==='active'?'Active · renews Sep 2':'Portfolio planning enabled'}</span></div><span>›</span></button><div class="setting"><div><b>Export or delete data</b><span>Privacy controls</span></div><span>›</span></div></div><div class="card"><span class="section-label">Session</span>${btn('Sign out','auth')}${btn('Clear local data','auth','ghost')}<p class="meta">Clearing local data requires confirmation and does not delete the workspace.</p></div></section>`; }
  function appearance() { return `<section class="screen">${top('Appearance','Make Longview comfortable to read and use.',{label:'Reset',go:'appearance'},true)}<div class="field"><label>Theme</label><div class="swatches">${['classic','ocean','forest','sunset'].map(x=>`<button class="swatch-choice ${appState.palette===x?'on':''}" data-palette="${x}"><i class="swatch ${x}"></i>${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div></div><div class="field"><label>Mode</label><div class="choices">${['light','dark'].map(x=>`<button class="choice ${appState.mode===x?'on':''}" data-mode="${x}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div></div><div class="field"><label>Reading font</label><div class="choices">${['lora','inter','outfit','fira','caveat'].map(x=>`<button class="choice ${appState.font===x?'on':''}" data-font="${x}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div></div><div class="field"><label>Text size</label><div class="choices">${['small','default','large','xlarge'].map(x=>`<button class="choice ${appState.size===x?'on':''}" data-size="${x}">${x==='xlarge'?'Extra large':x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div></div><div class="preview"><span class="section-label">Live preview</span><h3>Validate onboarding with target users</h3><p>Run two focused sessions and capture where users fail to reach the first useful outcome.</p><span class="badge blue">60 min · Today</span></div>${btn('Apply appearance','settings','primary')}<p class="meta">Accessibility text scaling always takes precedence.</p></section>`; }

  function goal() { if(appState.edge==='plan-details-missing') return `<section class="screen">${top('Plan not found','It may have been removed in another session.','',true)}<div class="empty" style="margin-top:38px"><div class="empty-icon">?</div><h2>This Plan is no longer available</h2><p>No stale Plan details are shown.</p>${btn('Return to Plans','portfolio','primary')}</div></section>`; if(appState.edge==='plan-details-error') return `<section class="screen">${top('Plan details unavailable','The saved Plan is unchanged.','',true)}<div class="empty" style="margin-top:38px"><div class="empty-icon">!</div><h2>Couldn’t load this Plan</h2><p>Check the connection and retry the same Plan.</p><button class="btn primary" data-action="clear-edge">Try again</button>${btn('Return to Plans','portfolio','ghost')}</div></section>`; return `<section class="screen">${top('Build SaaS Startup','Plan details',{label:'•••',go:'decisions'},true)}<div class="row" style="align-items:start"><div style="flex:1.35"><div class="card"><div class="task-head"><div><h2 class="card-title">Build SaaS Startup</h2><p class="meta">3 tasks this week · target Oct 2026</p></div><span class="badge green">Primary focus</span></div><p class="card-copy">Validate a narrow customer problem and reach a repeatable first useful outcome before expanding product scope.</p><p class="meta">Why it matters · build a sustainable product around verified customer value</p></div><button class="card task-card" data-go="goal-task" style="width:100%;text-align:left"><span class="section-label">Today’s task</span><h2 class="card-title">Validate onboarding with target users</h2><p class="card-copy">Run two sessions and capture where users fail to reach first value.</p><span class="badge blue">Open task ›</span></button></div><div style="flex:.8"><div class="card"><span class="section-label">Timeline</span><h2 class="card-title">Jul 17 – Oct 30, 2026</h2><p class="meta">Mon, Tue, Thu · 6 hours/week</p></div><div class="card"><span class="section-label">Thinking</span><button class="setting" data-go="decisions"><b>Decisions</b><span>3 ›</span></button><button class="setting" data-go="research"><b>Research & Goal Brief</b><span>v3 ›</span></button><button class="setting" data-go="history"><b>Task history</b><span>12 events ›</span></button></div>${btn('Ask Clara about this Plan','goal-clara-home','primary')}</div></div></section>`; }
  function goalTask() { return `<section class="screen">${top('Today’s task','Build SaaS Startup',{label:'•••',go:'decisions'},true)}<div class="card task-card"><span class="badge blue">Scheduled today · 7:00 AM</span><h2 class="card-title" style="margin-top:10px">Validate onboarding with target users</h2><p class="card-copy">Run two focused sessions. Record the first point of confusion, whether users reach first value, and the exact words they use.</p><div class="metrics"><div class="metric"><b>60m</b><span>estimate</span></div><div class="metric"><b>Live</b><span>customer input</span></div><div class="metric"><b>W4</b><span>week</span></div></div><div class="row">${btn('Mark complete','completion-confirm','primary')}${btn('Reschedule','calendar')}</div></div>${btn('Ask Clara about this task','goal-clara-home')}</section>`; }
  function goalAchievement() { return `<section class="screen">${top('Plan achieved','Completed Oct 30, 2026',{label:'•••',go:'history'},true)}${appState.edge==='reflection-save-error'?`<div class="notice" style="border-color:var(--rose)"><span class="badge rose">Not saved</span><div><strong>Your reflection draft is still here</strong><span>No reusable learning changed. Retry when the connection returns.</span></div></div>`:''}<div class="achievement-hero"><div class="achievement-mark">✓</div><div><span class="section-label">Build SaaS Startup</span><h2>Three design partners now reach first value every week.</h2><p>The outcome is complete. Capture what made it work before moving on.</p></div></div><div class="metrics"><div class="metric"><b>14</b><span>weeks</span></div><div class="metric"><b>46</b><span>actions</span></div><div class="metric"><b>6</b><span>decisions</span></div></div><div class="card reflection-card"><span class="section-label">Your reflection</span><h2 class="card-title">What changed because you followed through?</h2><div class="field"><label>How does this feel?</label><div class="choices reflection-moods"><button class="choice on" data-action="reflection-mood">Proud</button><button class="choice" data-action="reflection-mood">Relieved</button><button class="choice" data-action="reflection-mood">Energized</button><button class="choice" data-action="reflection-mood">Mixed</button></div></div><div class="field"><label>What made the difference?</label><textarea class="input" style="min-height:62px">Weekly customer sessions kept product decisions tied to evidence.</textarea></div><div class="field"><label>What should Clara remember?</label><input class="input" value="Validate first value before expanding scope."></div><div class="row"><button class="btn primary" data-action="save-reflection">${appState.edge==='reflection-save-error'?'Try saving again':'Save reflection'}</button>${btn('Review journey','history')}</div></div></section>`; }
  function taskHistory() { return `<section class="screen">${top('Task history','Build SaaS Startup · newest first',{label:'Filter'},true)}<div class="timeline"><div class="event"><b>Customer validation scheduled</b><span>Today · 7:00 AM · 60 min</span></div><div class="event"><b>Activation event defined</b><span>Fri, Jul 31 · “Reached first useful output”</span></div><div class="event"><b>Pricing interview moved</b><span>Wed → Thu because participant rescheduled</span></div><div class="event"><b>Onboarding baseline completed</b><span>Mon, Jul 27 · 3 sessions · 1 activation</span></div><div class="event"><b>Plan created</b><span>Fri, Jul 17</span></div></div></section>`; }
  function decisions() { return `<section class="screen">${top('Decisions','Reasoning that should survive the week.',{label:'Add'},true)}<div class="card"><div class="task-head"><h2 class="card-title">Validate first value before adding features</h2><span class="badge green">Current</span></div><p class="card-copy">Customer evidence matters more than expanding scope before activation is repeatable.</p><p class="meta">Jul 28 · linked to onboarding validation</p></div><div class="card"><div class="task-head"><h2 class="card-title">Build the dashboard first</h2><span class="badge">Superseded</span></div><p class="card-copy">Early interviews showed users need a guided first outcome before reporting.</p><p class="meta">Jul 21 · replaced Jul 30</p></div><button class="btn" data-action="decision">Record a decision</button></section>`; }
  function research() {
    if(appState.edge==='research-error') return `<section class="screen">${top('Research & Goal Brief','Build SaaS Startup',{label:'?'},true)}${briefCard()}<div class="empty" style="margin-top:30px"><div class="empty-icon">R</div><h2>Research is unavailable</h2><p>Your current Goal Brief and saved cards are unchanged.</p><button class="btn primary" data-action="fetch-research">Try again</button>${btn('Review saved cards','research-cards')}</div></section>`;
    return `<section class="screen">${top('Research & Goal Brief','Build SaaS Startup',{label:'?'},true)}${briefCard()}<div class="empty" style="margin-top:28px"><div class="empty-icon">R</div><h2>Bring in fresh evidence</h2><p>Clara can find focused product and customer evidence for this Plan. You decide what belongs in the Goal Brief.</p><button class="btn primary" data-action="fetch-research">Find research cards</button>${btn('View brief history','brief-history','ghost')}</div></section>`;
  }
  function briefCard() { return `<div class="card"><span class="section-label">Current Goal Brief · v${appState.briefVersion}</span><h2 class="card-title">Validate a repeatable first useful outcome</h2><p class="card-copy">Prioritize customer evidence, activation, and a narrow onboarding path. Avoid expanding product scope until first value is repeatable.</p></div>`; }
  function researchLoading() { return `<section class="screen">${top('Finding research','Clara is using this Plan and Goal Brief v3.','',true)}<div class="loading"><div class="spinner"></div>Finding focused, recent evidence and checking sources…</div></section>`; }
  function researchCards() { return `<section class="screen">${top('Review research','3 new cards · Build SaaS Startup',{label:'?'},true)}${researchItem('Define one observable activation event','Choose the first user behavior that demonstrates the product delivered useful value.','Product analytics review',0)}${researchItem('Ask about recent behavior, not longview','Concrete past actions reveal stronger constraints than hypothetical willingness.','Customer discovery guidance',1)}${researchItem('Test onboarding with target users','Observe where representative users hesitate, abandon, or require explanation before first value.','Usability study plan',2)}<p class="meta">Accepted cards create a Goal Brief proposal. They never update it automatically.</p>${appState.researchAccepted?btn(`Review ${appState.researchAccepted} accepted insight${appState.researchAccepted>1?'s':''}`,'brief-preview','primary'):''}</section>`; }
  function researchItem(title,copy,source,index) { return `<div class="card research"><div class="task-head"><h2 class="card-title">${title}</h2><span class="badge violet">${index===0?'New':'Research'}</span></div><p class="card-copy">${copy}</p><div class="research-source"><span>${source}</span><span>Reviewed by Clara</span></div><div class="task-actions"><button class="btn primary" data-action="accept-research">Accept</button><button class="btn" data-action="reject-research">Reject</button><button class="btn">Later</button></div></div>`; }
  function briefPreview() { if(appState.edge==='brief-conflict') return `<section class="screen">${top('Goal Brief changed','A newer version was saved in another session.','',true)}<div class="empty" style="margin-top:38px"><div class="empty-icon">!</div><h2>Refresh before creating a version</h2><p>Your accepted evidence is still saved and no brief was overwritten.</p>${btn('Review current brief','research','primary')}${btn('Keep proposal for later','research-cards','ghost')}</div></section>`; return `<section class="screen">${top('Confirm Goal Brief update',`${appState.researchAccepted||2} accepted insights · creates version ${appState.briefVersion+1}`,'',true)}<div class="card"><span class="section-label">Current · v${appState.briefVersion}</span><p class="card-copy">Prioritize customer evidence, activation, and a narrow onboarding path before expanding scope.</p><div class="diff"><b>Proposed addition</b><br>Define activation as reaching the first useful output without assistance, test it with five target users, and capture the first point of confusion in every session.</div><span class="badge violet">${appState.researchAccepted||2} accepted research cards</span></div><button class="btn primary" data-action="update-brief">Update Goal Brief</button>${btn('Edit wording','brief-preview')}${btn('Not now · keep for later','research-cards','ghost')}</section>`; }
  function briefHistory() { return `<section class="screen">${top('Goal Brief history','Build SaaS Startup','',true)}<div class="card"><div class="version"><b>v${appState.briefVersion}<br><span class="badge green">Current</span></b><div><h3>Activation and onboarding strategy</h3><p>Accepted research · Aug 2</p></div></div><div class="version"><b>v3</b><div><h3>Six-hour weekly allocation added</h3><p>Portfolio decision · Jul 30</p></div></div><div class="version"><b>v2</b><div><h3>Validation-first strategy clarified</h3><p>Clara suggestion · Jul 21</p></div></div><div class="version"><b>v1</b><div><h3>Initial Goal Brief</h3><p>Created from your words · Jul 17</p></div></div></div>${btn('Return to current brief','research')}</section>`; }

  function plans() { return `<section class="screen">${top('Choose your Longview plan','Start free. Upgrade when Clara and research should carry more planning load.','',true)}<div class="prices"><div class="price"><h2>Free</h2><div class="amount">₹0</div><ul><li>2 active Plans</li><li>Manual daily scheduling</li><li>Basic task history</li></ul><button class="btn">Current plan</button></div><div class="price featured"><span class="badge blue">Recommended</span><h2 style="margin-top:9px">Longview Pro</h2><div class="amount">₹499 <span class="meta">/ month</span></div><ul><li>Unlimited Plans</li><li>Clara daily planning</li><li>Research and brief versions</li></ul>${btn('Start 14-day trial','checkout','primary')}</div><div class="price"><h2>Annual</h2><div class="amount">₹4,999 <span class="meta">/ year</span></div><ul><li>Everything in Pro</li><li>Two months included</li><li>Access on every device</li></ul>${btn('Choose annual','checkout')}</div></div><p class="meta">${platform==='android'||platform==='ios'?`${config.purchase} handles payment and renewal.`:'India uses Razorpay; other regions use Stripe.'}</p></section>`; }
  function checkout() {
    if(appState.edge==='payment-error') return `<section class="screen">${top('Payment wasn’t completed','Your Free plan is still active.','',true)}<div class="empty" style="margin-top:34px"><div class="empty-icon">!</div><h2>Nothing was charged</h2><p>The payment provider did not confirm the subscription. Retry or choose another method.</p><button class="btn primary" data-action="retry-payment">Try again</button>${btn('Choose another plan','plans')}${btn('Stay on Free','settings','ghost')}</div></section>`;
    const native=platform==='android'||platform==='ios'; return `<section class="screen">${top('Confirm Longview Pro','14 days free, then ₹499/month. Cancel any time.','',true)}<div class="card"><div class="task-head"><h2 class="card-title">Longview Pro monthly</h2><span class="badge blue">Trial</span></div><div class="setting"><div><b>Due today</b><span>Trial begins immediately</span></div><b>₹0</b></div><div class="setting"><div><b>First renewal</b><span>Aug 16, 2026</span></div><b>₹499</b></div></div><div class="notice"><span class="badge blue">${config.purchase}</span><div><strong>${native?'Continue in the secure store sheet':'Continue to secure hosted checkout'}</strong><span>${native?'Renewal is managed from your store account.':'Choose the provider for your billing country.'}</span></div></div>${native?`<button class="btn primary" data-action="pay">Continue with ${config.purchase}</button>`:`<div class="row">${btn('Stripe · international','stripe','primary')}${btn('Razorpay · India','razorpay')}</div>`}${btn('Restore existing purchase','manage','ghost')}</section>`; }
  function providerCheckout(kind) {
    const native=platform==='android'||platform==='ios'; if(native) return `<section class="screen">${top(`${kind==='stripe'?'Stripe':'Razorpay'} checkout`,'Web and PWA purchase path','',true)}<div class="empty" style="margin-top:35px"><div class="empty-icon">${kind==='stripe'?'S':'R'}</div><h2>Native purchase stays in ${config.purchase}</h2><p>This provider appears only on Longview Web and PWA. The store build uses native subscription billing.</p>${btn(`View ${config.purchase} version`,'checkout','primary')}</div></section>`;
    const stripe=kind==='stripe'; return `<section class="screen">${top('Secure checkout',`${stripe?'International':'India'} Web and PWA · powered by ${stripe?'Stripe':'Razorpay'}`,'',true)}<div class="checkout ${stripe?'stripe':'razor'}"><div class="checkout-head"><span>Longview Pro</span><span>${stripe?'stripe':'Razorpay'}</span></div><div class="checkout-body"><div class="order"><b>${stripe?'$5.99 USD':'₹499'} / month</b><span>14 days free · first renewal Aug 16, 2026</span></div><div class="pay-field"><label>Email</label><div class="pay-input">alok@example.com</div></div>${stripe?`<div class="pay-field"><label>Card information</label><div class="pay-input">1234 1234 1234 1234   MM / YY   CVC</div></div><div class="pay-field"><label>Billing country</label><div class="pay-input">United States</div></div>`:`<div class="choices"><button class="choice on">UPI</button><button class="choice">Card</button><button class="choice">Netbanking</button></div><div class="pay-field"><label>UPI ID</label><div class="pay-input">name@bank</div></div>`}<button class="pay" data-action="pay">Start trial</button><p style="margin:0;color:#6d6e78;font-size:8px;text-align:center">Secure payment · cancel any time · returns to Longview</p></div></div></section>`; }
  function paymentSuccess() { return `<section class="screen">${top('Longview Pro is active','Your entitlement is available on every linked device.','',false)}<div class="empty" style="margin-top:34px"><div class="empty-icon">✓</div><h2>Welcome to Pro</h2><p>Clara daily planning, unlimited Plans, research cards, and Goal Brief history are now available.</p>${btn('Continue to Today','today','primary')}${btn('Manage subscription','manage')}</div></section>`; }
  function manage() {
    if(appState.edge==='grace') return `<section class="screen">${top('Subscription','Your Plan is in a payment grace period.','',true)}<div class="notice" style="border-color:var(--amber)"><span class="badge amber">Payment issue</span><div><strong>Pro remains active until Aug 9</strong><span>Update payment with ${config.purchase} to avoid interruption.</span></div></div><div class="card"><div class="setting"><div><b>Current access</b><span>All Pro features</span></div><span class="badge green">Available</span></div><div class="setting"><div><b>Recovery deadline</b><span>Aug 9, 2026</span></div><span>7 days</span></div></div><button class="btn primary" data-go="checkout">Resolve payment</button>${btn('Restore / refresh access','manage')}</section>`;
    return `<section class="screen">${top('Subscription','Access is shared across every linked device.','',true)}<div class="card"><div class="task-head"><div><h2 class="card-title">${appState.subscription==='active'?'Longview Pro':'Free'}</h2><p class="meta">Purchased through ${config.purchase}</p></div><span class="badge ${appState.subscription==='active'?'green':''}">${appState.subscription==='active'?'Active':'Current'}</span></div>${appState.subscription==='active'?`<div class="setting"><div><b>Renews</b><span>Sep 2, 2026</span></div><b>₹499</b></div><div class="setting"><div><b>Entitlement</b><span>Android · iOS · Web · PWA</span></div><span class="badge blue">Synced</span></div>`:''}</div>${appState.subscription==='active'?btn(`Manage or cancel with ${config.purchase}`,'manage'):btn('View Pro plans','plans','primary')}${btn('Restore / refresh access','manage','ghost')}</section>`; }

  function screenHtml() {
    const map={welcome,auth,explain,availability,'today-empty':todayEmpty,'plan-create':planCreate,'plan-confirm':planConfirm,reveal,today,'completion-confirm':completionConfirm,'completion-done':completionDone,portfolio,'clara-read':claraRead,'clara-home':()=>claraHome(false),'clara-actions':()=>claraActions(false),'clara-action-detail':()=>claraActionDetail(false),'clara-chat':()=>claraChat(false),'clara-preview':claraPreview,kanban,calendar,'schedule-loading':scheduleLoading,'schedule-proposal':scheduleProposal,'schedule-approved':scheduleApproved,'break-confirm':breakConfirm,'break-done':breakDone,settings,appearance,goal,'goal-task':goalTask,'goal-achievement':goalAchievement,history:taskHistory,decisions,research,'research-loading':researchLoading,'research-cards':researchCards,'brief-preview':briefPreview,'brief-history':briefHistory,'goal-clara-home':()=>claraHome(true),'goal-clara-actions':()=>claraActions(true),'goal-clara-detail':()=>claraActionDetail(true),'goal-clara-chat':()=>claraChat(true),plans,checkout,stripe:()=>providerCheckout('stripe'),razorpay:()=>providerCheckout('razorpay'),'payment-success':paymentSuccess,manage};
    return (map[appState.route]||welcome)();
  }

  function applyAppearance() {
    const el=document.documentElement; el.dataset.palette=appState.palette;el.dataset.mode=appState.mode;el.dataset.font=appState.font;el.dataset.size=appState.size;
  }
  function render() {
    applyAppearance(); root.innerHTML=scaffold(screenHtml());
    if(appState.route==='settings' && appState.anonymous) {
      root.querySelector('.screen')?.insertAdjacentHTML('beforeend','<div class="notice"><div><strong>Keep access to this workspace</strong><span>Link a Google account before signing out so you can return later.</span></div></div>');
    }
    if(appState.route==='plan-confirm' && appState.edge==='plan-save-error') {
      root.querySelector('[data-action="create-plan"]')?.insertAdjacentHTML('beforebegin','<div class="notice" style="border-color:var(--rose)"><div><strong>Your Plan wasn’t saved</strong><span>Check your connection and try again. Your review is still here.</span></div></div>');
    }
    root.querySelectorAll('[data-action]').forEach(el=>el.onclick=e=>{e.stopPropagation();performAction(el.dataset.action,el);});
    window.history.replaceState(null,'',`#${appState.route}`);
    parent.postMessage({type:'longview:route',platform,route:appState.route},'*');
  }
  function go(route,push=true) {
    if(!routes.includes(route)) return;
    appState.demoMenu='';
    const title=document.getElementById('planTitle'), why=document.getElementById('planWhy'); if(title)appState.planTitle=title.value||appState.planTitle;if(why)appState.planWhy=why.value||appState.planWhy;
    if(push && route!==appState.route) appState.stack.push(appState.route); appState.route=route; appState.toast=''; render();
  }
  function back() { const route=appState.stack.pop() || (routeGroup()==='goal'?'goal':routeGroup()==='subscription'?'settings':'today'); appState.route=route;appState.toast='';render(); }
  function toast(msg) { appState.toast=msg;render();setTimeout(()=>{if(appState.toast===msg){appState.toast='';render();}},1800); }
  function setEdge(edge) {
    appState.edge=edge;appState.demoMenu='';
    const target={'auth-error':'auth','auth-popup':'auth','auth-conflict':'auth','workspace-error':'auth','availability-empty':'availability','availability-save-error':'availability','plan-save-error':'plan-confirm','plans-loading':'portfolio','plans-empty':'portfolio','plans-load-error':'portfolio','plan-details-missing':'goal','plan-details-error':'goal','today-prepare-error':'today','completion-save-error':'completion-confirm','completion-duplicate':'completion-done',offline:'today','no-task':'today','draft-error':'reveal','schedule-error':'calendar','run-cancelled':'schedule-loading','run-timeout':'calendar','partial-recovery':'calendar','research-error':'research','brief-conflict':'brief-preview','reflection-save-error':'goal-achievement','payment-error':'checkout',grace:'manage','clara-error':'clara-read','clara-timeout':'clara-read','clara-malformed':'clara-read','clara-clarification':'clara-read','clara-injection':'clara-read','approval-stale':'clara-preview','approval-duplicate':'clara-preview'}[edge];
    if(target) appState.route=target; render();
  }
  function reset() { Object.assign(appState,{route:'welcome',stack:[],edge:'normal',signedIn:false,anonymous:false,planCreated:false,taskDone:false,scheduleApproved:false,breakTaken:false,researchAccepted:0,briefVersion:3,subscription:'free',palette:'ocean',mode:'dark',font:'lora',size:'default',toast:'',planTitle:'Build SaaS Startup',planWhy:'Create a sustainable product business around a validated customer problem.'});render(); }

  function performAction(action,target) {
    if(action==='reset')return reset(); if(action==='clear-edge'){appState.edge='normal';return render();}
    if(action==='toggle-route-menu'){appState.demoMenu=appState.demoMenu==='route'?'':'route';return render();}
    if(action==='toggle-edge-menu'){appState.demoMenu=appState.demoMenu==='edge'?'':'edge';return render();}
    if(action==='provider'||action==='google'){appState.signedIn=true;appState.anonymous=false;appState.edge='normal';return go('explain');}
    if(action==='anonymous'){appState.anonymous=true;appState.signedIn=true;return go('explain');}
    if(action==='create-plan'){appState.planCreated=true;return go('reveal');}
    if(action==='complete-task'){appState.edge='normal';appState.taskDone=true;return go('completion-done');}
    if(action==='reflection-mood'){target.parentElement.querySelectorAll('.choice').forEach(el=>el.classList.remove('on'));target.classList.add('on');return;}
    if(action==='save-reflection')return toast('Reflection saved · Clara can use this learning');
    if(action==='generate-schedule'){appState.edge='normal';go('schedule-loading');return setTimeout(()=>go('schedule-proposal'),900);}
    if(action==='approve-day'){appState.scheduleApproved=true;go('schedule-approved');return;}
    if(action==='confirm-break'){appState.breakTaken=true;appState.scheduleApproved=false;go('break-done');return;}
    if(action==='apply-clara'){appState.toast='Schedule updated · undo available';go('today');return;}
    if(action==='fetch-research'){appState.edge='normal';go('research-loading');return setTimeout(()=>go('research-cards'),900);}
    if(action==='accept-research'){appState.researchAccepted++;return toast('Insight accepted · ready for brief review');}
    if(action==='reject-research')return toast('Card rejected · it remains in research history');
    if(action==='update-brief'){appState.briefVersion++;appState.researchAccepted=0;go('brief-history');return;}
    if(action==='pay'){appState.edge='normal';appState.subscription='active';go('payment-success');return;}
    if(action==='retry-payment'){appState.edge='normal';go(platform==='android'||platform==='ios'?'checkout':'stripe');return;}
    if(action==='retry-draft'){appState.edge='normal';go('reveal');return;}
    if(action==='retry-clara'){appState.edge='normal';go(appState.route.startsWith('goal')?'goal-clara-chat':'clara-chat');return;}
    if(action==='install')return toast('PWA install prompt opened');
    if(action==='decision')return toast('Decision draft opened');
    if(action==='reminder')return toast('Review reminder added for Saturday');
    if(action==='speak')return toast('Listening · speak your Plan');
    if(action==='prompt')return toast(`Prompt added: ${target.textContent.trim()}`);
    if(action==='send')return toast('Message sent to Clara');
    if(action==='toggle-day'){target.classList.toggle('on');return;}
  }

  root.addEventListener('click', e => {
    const demoRoute=e.target.closest('[data-demo-route]');if(demoRoute){go(demoRoute.dataset.demoRoute,false);return;}
    const demoEdge=e.target.closest('[data-demo-edge]');if(demoEdge){setEdge(demoEdge.dataset.demoEdge);return;}
    const goEl=e.target.closest('[data-go]'); if(goEl){go(goEl.dataset.go);return;}
    if(e.target.closest('[data-back]')){back();return;}
    const palette=e.target.closest('[data-palette]');if(palette){appState.palette=palette.dataset.palette;render();return;}
    const mode=e.target.closest('[data-mode]');if(mode){appState.mode=mode.dataset.mode;render();return;}
    const font=e.target.closest('[data-font]');if(font){appState.font=font.dataset.font;render();return;}
    const size=e.target.closest('[data-size]');if(size){appState.size=size.dataset.size;render();return;}
    const actionEl=e.target.closest('[data-action]');if(actionEl)performAction(actionEl.dataset.action,actionEl);
  });
  window.addEventListener('message', e=>{ if(e.data?.type==='longview:navigate' && routes.includes(e.data.route)) go(e.data.route,false); if(e.data?.type==='longview:edge') setEdge(e.data.edge||'normal'); if(e.data?.type==='longview:reset') reset(); });
  render();
})();
